`timescale 1ns/1ps

module m_vlsit_csr_dvp #(
  // Parameter Description: select same-clock or asynchronous bus-to-register crossing logic.
  // Parameter values: 0 (synchronous) or 1 (asynchronous); default follows the workbook.
  // Parameter unit: none
  parameter logic [31:0] PARA_ASYNCHRONOUS = 32'd0,
  localparam logic [31:0] LPARA_ADDR_W = 32'd16,
  localparam logic [31:0] LPARA_DATA_W = 32'd32,
  localparam logic [31:0] LPARA_STRB_W = 32'd4,
  localparam logic [31:0] LPARA_SYNC_STAGES = 32'd2,
  localparam logic [31:0] LPARA_DVP_VERSION_OFFSET = 32'h0000,
  localparam logic [31:0] LPARA_DVP_CTRL_OFFSET = 32'h0004,
  localparam logic [31:0] LPARA_DVP_WMARK_OFFSET = 32'h0008,
  localparam logic [31:0] LPARA_DVP_TIMEOUT_OFFSET = 32'h000c,
  localparam logic [31:0] LPARA_DVP_FIFO_STS_OFFSET = 32'h0010,
  localparam logic [31:0] LPARA_DVP_FIFO_LEVEL_OFFSET = 32'h0014
) (
  // APB clock and reset
  input  wire                     i_clk_apb,
  input  wire                     i_rst_n_apb,

  // Register clock and reset (used only in asynchronous mode)
  input  wire                     i_clk_reg,
  input  wire                     i_rst_n_reg,

  // APB slave interface
  input  wire                     i_apb_psel,
  input  wire                     i_apb_penable,
  input  wire                     i_apb_pwrite,
  input  wire  [LPARA_ADDR_W-1:0] i_apb_paddr,
  input  wire  [LPARA_DATA_W-1:0] i_apb_pwdata,
  input  wire  [LPARA_STRB_W-1:0] i_apb_pstrb,
  input  wire  [2:0]              i_apb_pprot,
  output logic                    o_apb_pready,
  output logic                    o_apb_pslverr,
  output logic [LPARA_DATA_W-1:0] o_apb_prdata,

  // Access check control
  input  wire                     i_protect_en,
  input  wire                     i_slverr_en,

  // Register dvp_version
  input  wire  [15:0]             i_dvp_version_major,
  input  wire  [15:0]             i_dvp_version_minor,

  // Register dvp_ctrl
  output logic                    o_dvp_ctrl_pclk_mode,
  output logic                    o_dvp_ctrl_capture_en,

  // Register dvp_wmark
  output logic [31:0]             o_dvp_wmark_level,

  // Register dvp_timeout
  output logic [31:0]             o_dvp_timeout_cycles,

  // Register dvp_fifo_sts
  output logic                    o_dvp_fifo_sts_ovf,
  input  wire                     i_hw_wdata_dvp_fifo_sts_ovf,
  input  wire                     i_hw_we_dvp_fifo_sts_ovf,
  input  wire                     i_dvp_fifo_sts_full,
  input  wire                     i_dvp_fifo_sts_empty,
  input  wire                     i_dvp_fifo_sts_active,

  // Register dvp_fifo_level
  input  wire  [31:0]             i_dvp_fifo_level_count
);

  // Internal signal declarations
  logic w_apb_setup;
  logic w_apb_prot_ok;
  logic w_apb_slverr;
  logic w_apb_complete;
  logic w_apb_wr;
  logic w_apb_rd;
  logic [LPARA_ADDR_W-1:0] reg_addr;
  logic [LPARA_DATA_W-1:0] reg_wdata;
  logic [LPARA_STRB_W-1:0] reg_wstrb;
  logic [LPARA_DATA_W-1:0] w_wmask;
  logic reg_slverr;
  logic w_rd_en;
  logic w_wr_en;
  logic w_rd_ack_fall;
  logic [LPARA_DATA_W-1:0] w_rdata_nxt;
  logic [LPARA_DATA_W-1:0] reg_rdata;
  logic w_clk_reg;
  logic w_rst_n_reg;
  logic [LPARA_DATA_W-1:0] w_dvp_version_value;
  logic w_we_dvp_ctrl;
  logic reg_dvp_ctrl_pclk_mode;
  logic w_dvp_ctrl_pclk_mode_nxt;
  logic reg_dvp_ctrl_capture_en;
  logic w_dvp_ctrl_capture_en_nxt;
  logic [LPARA_DATA_W-1:0] w_dvp_ctrl_value;
  logic w_we_dvp_wmark;
  logic [31:0] reg_dvp_wmark_level;
  logic [31:0] w_dvp_wmark_level_nxt;
  logic [LPARA_DATA_W-1:0] w_dvp_wmark_value;
  logic w_we_dvp_timeout;
  logic [31:0] reg_dvp_timeout_cycles;
  logic [31:0] w_dvp_timeout_cycles_nxt;
  logic [LPARA_DATA_W-1:0] w_dvp_timeout_value;
  logic w_we_dvp_fifo_sts;
  logic reg_dvp_fifo_sts_ovf;
  logic w_dvp_fifo_sts_ovf_nxt;
  logic [LPARA_DATA_W-1:0] w_dvp_fifo_sts_value;
  logic [LPARA_DATA_W-1:0] w_dvp_fifo_level_value;

  // The parameter selects the register clock/reset for the chosen bus front end.
  assign w_clk_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_clk_reg : i_clk_apb;
  assign w_rst_n_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_rst_n_reg : i_rst_n_apb;


  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // A transfer is in error when the protection, the word alignment or the byte strobes fail
  // while i_slverr_en is 1.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en ? (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb[LPARA_STRB_W-1:0] & i_apb_pwrite)) : 1'b0;

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Write byte strobes are captured with the write payload and expanded to field-bit masks.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wstrb
    if (!i_rst_n_apb)
      reg_wstrb <= '0;
    else if (w_apb_wr)
      reg_wstrb <= i_apb_pstrb[LPARA_STRB_W-1:0];
  end
  generate
    for (genvar gen_lane = 0; gen_lane < LPARA_STRB_W; gen_lane++) begin : gen_apb_wmask
      assign w_wmask[(gen_lane * 8) +: 8] = {8{reg_wstrb[gen_lane]}};
    end
  endgenerate

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Per-register write/read address enables.
  assign w_we_dvp_ctrl = w_wr_en & (reg_addr == LPARA_DVP_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dvp_wmark = w_wr_en & (reg_addr == LPARA_DVP_WMARK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dvp_timeout = w_wr_en & (reg_addr == LPARA_DVP_TIMEOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dvp_fifo_sts = w_wr_en & (reg_addr == LPARA_DVP_FIFO_STS_OFFSET[LPARA_ADDR_W-1:0]);

  // Elaboration selects one clock architecture for this single RTL module.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_csr

      // Async-only request, acknowledge, and synchronizer state.
      logic w_rd_ack;
      logic w_rd_ack_bus;
      logic reg_rd_req;
      logic w_rd_req_nxt;
      logic reg_rd_ack_bus_dly;
      logic w_wr_ack;
      logic w_wr_ack_bus;
      logic reg_wr_req;
      logic w_wr_req_nxt;
      logic w_wr_ack_fall;
      logic reg_wr_ack_bus_dly;
      logic w_rd_req_reg;
      logic reg_rd_req_reg_dly;
      logic w_wr_req_reg;
      logic reg_wr_req_reg_dly;
      logic w_pready_nxt;
      logic reg_pready;

      // Read request and acknowledge toggles cross between the APB and register clocks.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_rd_ack),
        .o_q         (w_rd_ack_bus)
      );

      // APB read request is set on a read and cleared by its synchronized acknowledge.
      assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
      assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
        if (!i_rst_n_apb) begin
          reg_rd_req         <= 1'b0;
          reg_rd_ack_bus_dly <= 1'b0;
        end else begin
          reg_rd_req         <= w_rd_req_nxt;
          reg_rd_ack_bus_dly <= w_rd_ack_bus;
        end
      end

      // APB write request uses an independent request/acknowledge toggle.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_wr_ack),
        .o_q         (w_wr_ack_bus)
      );
      assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
      assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
        if (!i_rst_n_apb) begin
          reg_wr_req         <= 1'b0;
          reg_wr_ack_bus_dly <= 1'b0;
        end else begin
          reg_wr_req         <= w_wr_req_nxt;
          reg_wr_ack_bus_dly <= w_wr_ack_bus;
        end
      end

      // Read request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_rd_req),
        .o_q         (w_rd_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rd_req_reg
        if (!i_rst_n_reg)
          reg_rd_req_reg_dly <= 1'b0;
        else
          reg_rd_req_reg_dly <= w_rd_req_reg;
      end
      assign w_rd_en  = ~reg_rd_req_reg_dly & w_rd_req_reg;
      assign w_rd_ack = reg_rd_req_reg_dly;

      // Write request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_wr_req),
        .o_q         (w_wr_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_wr_req_reg
        if (!i_rst_n_reg)
          reg_wr_req_reg_dly <= 1'b0;
        else
          reg_wr_req_reg_dly <= w_wr_req_reg;
      end
      assign w_wr_en  = ~reg_wr_req_reg_dly & w_wr_req_reg;
      assign w_wr_ack = reg_wr_req_reg_dly;

      // PREADY pulses after an acknowledged operation or a SETUP-phase error.
      assign w_pready_nxt = w_rd_ack_fall | w_wr_ack_fall | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end else begin : g_sync_csr

      // Synchronous-only request capture and response state.
      logic reg_rd_capture;
      logic reg_wr_capture;
      logic w_pready_nxt;
      logic reg_pready;

      // Read/write enables are delayed one cycle in synchronous mode.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_capture
        if (!i_rst_n_apb) begin
          reg_rd_capture <= 1'b0;
          reg_wr_capture <= 1'b0;
        end else begin
          reg_rd_capture <= w_apb_rd;
          reg_wr_capture <= w_apb_wr;
        end
      end
      assign w_rd_en = reg_rd_capture;
      assign w_wr_en = reg_wr_capture;
      assign w_rd_ack_fall = 1'b0;

      // PREADY pulses after an operation or a SETUP-phase error.
      assign w_pready_nxt = w_wr_en | w_rd_en | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end
  endgenerate

  // Register dvp_version: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_dvp_version_value
    w_dvp_version_value = '0;
    w_dvp_version_value[31:16] = i_dvp_version_major;
    w_dvp_version_value[15:0] = i_dvp_version_minor;
  end

  // dvp_ctrl_pclk_mode next value (rw): update only byte lanes selected by the bus strobe.
  assign w_dvp_ctrl_pclk_mode_nxt = (w_we_dvp_ctrl & (|w_wmask[1])) ? ((reg_wdata[1] & w_wmask[1]) | (reg_dvp_ctrl_pclk_mode & ~w_wmask[1])) : reg_dvp_ctrl_pclk_mode;

  // dvp_ctrl_capture_en next value (rw): update only byte lanes selected by the bus strobe.
  assign w_dvp_ctrl_capture_en_nxt = (w_we_dvp_ctrl & (|w_wmask[0])) ? ((reg_wdata[0] & w_wmask[0]) | (reg_dvp_ctrl_capture_en & ~w_wmask[0])) : reg_dvp_ctrl_capture_en;

  // Register dvp_ctrl: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_dvp_ctrl
    if (!w_rst_n_reg) begin
      reg_dvp_ctrl_pclk_mode <= 1'h0;
      reg_dvp_ctrl_capture_en <= 1'h0;
    end else begin
      reg_dvp_ctrl_pclk_mode <= w_dvp_ctrl_pclk_mode_nxt;
      reg_dvp_ctrl_capture_en <= w_dvp_ctrl_capture_en_nxt;
    end
  end

  // Register dvp_ctrl: output ports follow the flops.
  assign o_dvp_ctrl_pclk_mode = reg_dvp_ctrl_pclk_mode;
  assign o_dvp_ctrl_capture_en = reg_dvp_ctrl_capture_en;

  // Register dvp_ctrl: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_dvp_ctrl_value
    w_dvp_ctrl_value = '0;
    w_dvp_ctrl_value[1] = reg_dvp_ctrl_pclk_mode;
    w_dvp_ctrl_value[0] = reg_dvp_ctrl_capture_en;
  end

  // dvp_wmark_level next value (rw): update only byte lanes selected by the bus strobe.
  assign w_dvp_wmark_level_nxt = (w_we_dvp_wmark & (|w_wmask[31:0])) ? ((reg_wdata[31:0] & w_wmask[31:0]) | (reg_dvp_wmark_level & ~w_wmask[31:0])) : reg_dvp_wmark_level;

  // Register dvp_wmark: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_dvp_wmark
    if (!w_rst_n_reg) begin
      reg_dvp_wmark_level <= 32'h0;
    end else begin
      reg_dvp_wmark_level <= w_dvp_wmark_level_nxt;
    end
  end

  // Register dvp_wmark: output ports follow the flops.
  assign o_dvp_wmark_level = reg_dvp_wmark_level;

  // Register dvp_wmark: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_dvp_wmark_value
    w_dvp_wmark_value = '0;
    w_dvp_wmark_value[31:0] = reg_dvp_wmark_level;
  end

  // dvp_timeout_cycles next value (rw): update only byte lanes selected by the bus strobe.
  assign w_dvp_timeout_cycles_nxt = (w_we_dvp_timeout & (|w_wmask[31:0])) ? ((reg_wdata[31:0] & w_wmask[31:0]) | (reg_dvp_timeout_cycles & ~w_wmask[31:0])) : reg_dvp_timeout_cycles;

  // Register dvp_timeout: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_dvp_timeout
    if (!w_rst_n_reg) begin
      reg_dvp_timeout_cycles <= 32'h0;
    end else begin
      reg_dvp_timeout_cycles <= w_dvp_timeout_cycles_nxt;
    end
  end

  // Register dvp_timeout: output ports follow the flops.
  assign o_dvp_timeout_cycles = reg_dvp_timeout_cycles;

  // Register dvp_timeout: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_dvp_timeout_value
    w_dvp_timeout_value = '0;
    w_dvp_timeout_value[31:0] = reg_dvp_timeout_cycles;
  end

  // dvp_fifo_sts_ovf next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_dvp_fifo_sts_ovf_nxt = (i_hw_we_dvp_fifo_sts_ovf) ? i_hw_wdata_dvp_fifo_sts_ovf
                          : ((w_we_dvp_fifo_sts & (|w_wmask[3])) ? (reg_dvp_fifo_sts_ovf & ~(reg_wdata[3] & w_wmask[3])) : reg_dvp_fifo_sts_ovf);

  // Register dvp_fifo_sts: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_dvp_fifo_sts
    if (!w_rst_n_reg) begin
      reg_dvp_fifo_sts_ovf <= 1'h0;
    end else begin
      reg_dvp_fifo_sts_ovf <= w_dvp_fifo_sts_ovf_nxt;
    end
  end

  // Register dvp_fifo_sts: output ports follow the flops.
  assign o_dvp_fifo_sts_ovf = reg_dvp_fifo_sts_ovf;

  // Register dvp_fifo_sts: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_dvp_fifo_sts_value
    w_dvp_fifo_sts_value = '0;
    w_dvp_fifo_sts_value[3] = reg_dvp_fifo_sts_ovf;
    w_dvp_fifo_sts_value[2] = i_dvp_fifo_sts_full;
    w_dvp_fifo_sts_value[1] = i_dvp_fifo_sts_empty;
    w_dvp_fifo_sts_value[0] = i_dvp_fifo_sts_active;
  end

  // Register dvp_fifo_level: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_dvp_fifo_level_value
    w_dvp_fifo_level_value = '0;
    w_dvp_fifo_level_value[31:0] = i_dvp_fifo_level_count;
  end

  // Read data mux returns zero for addresses that do not map to a register.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (32'(reg_addr))
      LPARA_DVP_VERSION_OFFSET: w_rdata_nxt = w_dvp_version_value;
      LPARA_DVP_CTRL_OFFSET: w_rdata_nxt = w_dvp_ctrl_value;
      LPARA_DVP_WMARK_OFFSET: w_rdata_nxt = w_dvp_wmark_value;
      LPARA_DVP_TIMEOUT_OFFSET: w_rdata_nxt = w_dvp_timeout_value;
      LPARA_DVP_FIFO_STS_OFFSET: w_rdata_nxt = w_dvp_fifo_sts_value;
      LPARA_DVP_FIFO_LEVEL_OFFSET: w_rdata_nxt = w_dvp_fifo_level_value;
      default: w_rdata_nxt = '0;
    endcase
  end

  // Read response storage follows the selected clock architecture.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_rdata
      logic [LPARA_DATA_W-1:0] reg_rdata_bus;

      // Snapshot read data in the register clock domain.
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rdata
        if (!i_rst_n_reg)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end

      // The synchronized acknowledge qualifies the stable bundled read data.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata_bus
        if (!i_rst_n_apb)
          reg_rdata_bus <= '0;
        else if (w_rd_ack_fall)
          reg_rdata_bus <= reg_rdata;
      end
      assign o_apb_prdata = reg_rdata_bus;
    end else begin : g_sync_rdata
      // Synchronous read data is captured in the APB/register clock domain.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata
        if (!i_rst_n_apb)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end
      assign o_apb_prdata = reg_rdata;
    end
  endgenerate

endmodule
